// 由 _evidence/gen-character-sprites.mjs 生成，勿手改。
// 立绘走内联 base64：图床会把带透明通道的图转成 JPEG，白底会露在画面上。
export const CHARACTER_SPRITES: Record<string, Record<string, string>> = {
  '恋喰少女': {
    '伤心':
      'data:image/webp;base64,',
    '害羞':
      'data:image/webp;base64,',
    '平静':
      'data:image/webp;base64,',
    '惊讶':
      'data:image/webp;base64,',
    '生气':
      'data:image/webp;base64,',
    '高兴':
      'data:image/webp;base64,',
  },
};

/** 剧本情绪 → 立绘情绪。世界书里写「开心」「默认」，图是「高兴」「平静」。 */
const EMOTION_ALIAS: Record<string, string> = {
  开心: '高兴',
  高兴: '高兴',
  默认: '平静',
  普通: '平静',
  平常: '平静',
};

/** 取立绘：情绪对不上就回落到「平静」，再没有就取第一张。 */
export function spriteFor(speaker?: string, emotion?: string): string | undefined {
  if (!speaker) return undefined;
  const set = CHARACTER_SPRITES[speaker];
  if (!set) return undefined;
  const key = EMOTION_ALIAS[emotion ?? ''] ?? emotion ?? '';
  return set[key] ?? set['平静'] ?? Object.values(set)[0];
}
